checks.solution:
def infer(types, props, subclass, defined):
    known = {ind: set(classes) for ind, classes in types.items()}
    changed = True
    while changed:
        changed = False
        for ind in list(known):
            for cls in list(known[ind]):
                for sub, sup in subclass:
                    if sub == cls and sup not in known[ind]:
                        known[ind].add(sup)
                        changed = True
            for name, (base, prop, filler) in defined.items():
                if name in known[ind] or base not in known[ind]:
                    continue
                for other in props.get(ind, {}).get(prop, ()):
                    if filler in known.get(other, set()):
                        known[ind].add(name)
                        changed = True
                        break
    return {ind: known[ind] - set(types[ind]) for ind in types}

checks.test:
types = {"john": {"Person"}, "mary": {"Female"}, "rex": {"Dog"}, "zoe": {"Person"}}
props = {"john": {"has_child": {"mary"}}}
subclass = {("Female", "Person"), ("Dog", "Pet"), ("Pet", "Animal")}
defined = {"Parent": ("Person", "has_child", "Person")}

out = infer(types, props, subclass, defined)
assert out["mary"] == {"Person"}, out["mary"]
assert out["rex"] == {"Pet", "Animal"}, out["rex"]
assert out["john"] == {"Parent"}, "mary must be recognised as a Person first"
assert out["zoe"] == set(), "no child asserted concludes nothing either way"

necessary_only = infer(types, props, subclass | {("Parent", "Person")}, {})
assert necessary_only["john"] == set(), "a one-way axiom classifies nobody into the class"

assert infer({"a": {"X"}}, {}, {("X", "Y"), ("Y", "X")}, {}) == {"a": {"Y"}}
assert infer({}, {}, set(), {}) == {}
assert infer({"a": {"X"}}, {}, set(), {}) == {"a": set()}

childless = infer({"kim": {"Person"}}, {"kim": {"has_child": set()}}, set(), defined)
assert childless["kim"] == set(), "an empty property set is not evidence of membership"
